<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowRight, BookOpen, Check, CheckCheck, ChevronRight, CircleDot, ClipboardList, Database, FileSearch, Fingerprint, GitCompareArrows, GraduationCap, Landmark, Layers3, LockKeyhole, Megaphone, Network, ShieldCheck, Sparkles, WalletCards, X } from 'lucide-vue-next'
import { usePlatformStore } from '../stores/platform'
import { compareCapabilityRows } from '../services/professional'

const store = usePlatformStore()
const capabilities = [
  { id: 'subsidy', title: '惠民惠农资金比对', tag: '规则样例可演示', icon: WalletCards, description: '串联申报、公示与发放，辅助发现需核对的重复记录。', input: '申报名单、公示清单、发放明细', output: '重复申请及批次差异核对清单', access: '需主管部门授权提供完整、同口径清单；使用匿名业务标识并落实最小必要原则。', detail: '将同一批次的匿名申请标识进行比对，提示重复出现的记录。相同标识不直接代表重复领取，需核对撤回、补发和冲销情况。', sample: '申请标识 | 匿名对象 | 金额（元） | 发放批次\nHJ-001 | 演示对象甲 | 8000 | 2026-Q3\nHJ-002 | 演示对象乙 | 6000 | 2026-Q3\nHJ-001 | 演示对象甲 | 8000 | 2026-Q3', rule: '同批次同一匿名申请标识重复出现', question: '是否为重复登记、冲销调整或补发记录？请对照申报和实际到账凭证。', phase: '二期需授权数据', color: 'blue' },
  { id: 'procurement', title: '招投标异常筛查', tag: '规则样例可演示', icon: Landmark, description: '对照采购流程材料，让关键环节的缺项与差异更清晰。', input: '项目台账、报价记录、采购附件', output: '材料缺项与报价关联提示', access: '需采购主管部门授权项目数据和原始附件，完成字段口径、项目编码与权限约定。', detail: '对照项目登记表检查报价、评审记录与合同的材料完整性。页面只提示纸面材料缺项，不推断围标、串标等违法事实。', sample: '项目标识 | 预算金额（元） | 报价附件 | 评审记录\nCG-001 | 48000 | 缺失 | 已提供\nCG-002 | 36000 | 已提供 | 已提供\nCG-003 | 58000 | 已提供 | 缺失', rule: '项目材料字段标记为“缺失”', question: '原始归档是否完整？是否存在尚未上传的报价或评审记录？', phase: '二期需授权数据', color: 'cyan' },
  { id: 'expense', title: '津补贴及公务支出', tag: '规则样例可演示', icon: FileSearch, description: '让凭证、审批与支付记录相互印证，减少人工翻找。', input: '报销台账、凭证号、审批记录', output: '同凭证重复引用与时序核对', access: '需财务主管部门授权提供台账及凭证，对用途、可见范围和留存期限进行约定。', detail: '以匿名凭证编号比对重复引用记录，并提示核查是否存在重复登记或冲销调整。暂不接入真实财务系统。', sample: '记录标识 | 匿名凭证号 | 金额（元） | 支出事项\nBX-001 | D-1068 | 6800 | 设备维护\nBX-002 | D-1069 | 2300 | 材料采购\nBX-003 | D-1068 | 6800 | 设备维护', rule: '相同匿名凭证编号在台账中重复引用', question: '是否为同一业务重复登记、不同业务引用，或一笔为冲销调整？', phase: '二期需授权数据', color: 'blue' },
  { id: 'archive', title: '干部廉政档案', tag: '二期能力预览', icon: Fingerprint, description: '按授权组织履职资料与归档记录，呈现材料完整性。', input: '授权归档目录、材料登记信息', output: '归档完整性清单与更新时间提示', access: '须建立明确的数据授权、分级访问和审计机制；不生成政治倾向画像或个人违纪评分。', detail: '仅演示匿名材料目录的完整性检查，不采集真实人员信息，不基于档案记录频次进行个人风险认定。', sample: '材料标识 | 匿名档案号 | 材料类型 | 归档状态\nDA-001 | A-001 | 年度登记表 | 已归档\nDA-002 | A-001 | 更新确认单 | 缺失\nDA-003 | A-002 | 年度登记表 | 已归档', rule: '归档目录字段标记为“缺失”', question: '该材料是否适用、是否已经在线下归档？需由档案管理人员人工核实。', phase: '二期需专项授权', color: 'slate' },
  { id: 'education', title: '廉洁教育素材', tag: '二期能力预览', icon: GraduationCap, description: '从审核过的素材中整理专题内容，辅助开展日常教育。', input: '授权教育素材、主题与使用对象', output: '专题目录与教育提纲初稿', access: '需明确素材版权与使用范围，由工作人员审核内容、来源和适用性后发布。', detail: '按人工指定主题检索虚构素材目录，生成供审核的编排提纲。不会捏造真实案例、人物或案例出处。', sample: '素材标识 | 素材主题 | 素材名称 | 审核状态\nJY-001 | 集体资产管理 | 合同材料核验示例 | 已审核\nJY-002 | 财务规范 | 收付款凭证检查要点 | 已审核\nJY-003 | 集体资产管理 | 公开流程示例 | 待审核', rule: '仅将“已审核”素材纳入辅助编排', question: '素材来源与授权是否清晰？教育内容是否经过人工审核并符合使用场景？', phase: '二期需审核素材库', color: 'cyan' },
  { id: 'public', title: '属地舆情热点监测', tag: '二期能力预览', icon: Megaphone, description: '辅助归集授权公开信息，保留来源与人工研判空间。', input: '授权公开信息源、关键词与时间范围', output: '事件归集摘要与来源核对清单', access: '须限定合法公开信息来源、业务目的与权限边界；不采集个人政治倾向或形成个体画像。', detail: '演示匿名公开事项按主题归集，不代表真实舆情监控系统，不以信息热度直接推断事实或责任。', sample: '信息标识 | 事件主题 | 来源占位 | 核验状态\nYQ-001 | 村务公开咨询 | 演示公开来源A | 待核验\nYQ-002 | 道路维修诉求 | 演示公开来源B | 已核验\nYQ-003 | 村务公开咨询 | 演示公开来源C | 待核验', rule: '按主题归集，单列“待核验”来源记录', question: '是否为同一事项？原始信息是否准确、完整且处于允许使用的公开范围？', phase: '二期需来源授权', color: 'slate' },
]
type Capability = typeof capabilities[number]
const active = ref<Capability | null>(null)
const drawerTab = ref<'overview' | 'demo'>('overview')
const input = ref('')
const processing = ref(false)
const result = computed(() => active.value ? [...store.assistantResults].reverse().find(r => r.type === `capability:${active.value!.id}`) : undefined)
const resultLines = computed(() => result.value?.output.split('\n\n') || [])
const demoCount = computed(() => new Set(store.assistantResults.filter(r => r.type?.startsWith('capability:')).map(r => r.type)).size)

function open(capability: Capability) {
  active.value = capability; drawerTab.value = 'overview'
  input.value = [...store.assistantResults].reverse().find(r => r.type === `capability:${capability.id}`)?.input || capability.sample
}
async function compare() {
  if (!active.value || !input.value.trim() || processing.value) return
  const capability = active.value
  processing.value = true
  await new Promise(resolve => setTimeout(resolve, 750))
  const { recordCount, matches: selectedRows } = compareCapabilityRows(capability.id, input.value)
  const output = `比对范围\n本次读取 ${recordCount} 行结构化演示记录。\n\n命中规则\n${capability.rule}。\n\n${capability.id === 'education' ? '可编排素材' : '待人工核对记录'}\n${selectedRows.length ? selectedRows.map((row, index) => `${index + 1}. ${row}`).join('\n') : '当前输入未命中演示规则，请保持“|”分隔的样例格式。未命中不代表不存在其他问题。'}\n\n待核问题\n${capability.question}\n\n边界提醒\n本地规则样例结果，不代表已接入真实系统，不构成事实认定。`
  store.assistantResults.push({ id: `CAP-${Date.now()}`, type: `capability:${capability.id}`, task: capability.title, input: input.value, output, createdAt: new Date().toLocaleString('zh-CN', { hour12: false }), reviewed: false })
  store.addEvent('能力样例比对', `${capability.title}：对 ${recordCount} 条虚构记录执行本地演示规则`)
  processing.value = false
}
function confirmReview() {
  if (!result.value || result.value.reviewed) return
  result.value.reviewed = true
  store.addEvent('人工确认能力样例', `已查看${active.value?.title}演示结果及数据授权边界`)
}
</script>

<template>
